test("deriveAlternativeComparison: no criteria yields an empty comparison with a zero score", () => {
  const comparison = deriveAlternativeComparison([])
  assert.deepEqual(comparison, { rows: [], summaryScore: 0 })
})

test("deriveAlternativeComparison: a pass criterion becomes a match row", () => {
  const comparison = deriveAlternativeComparison([criterion({ result: "pass" })])
  assert.deepEqual(comparison.rows, [
    { rowId: "conditioner.care_direction", label: "Pflegerichtung", state: "match" },
  ])
  assert.equal(comparison.summaryScore, 1)
})

test("deriveAlternativeComparison: caution/fail/unknown map to partial/mismatch/unknown", () => {
  const comparison = deriveAlternativeComparison([
    criterion({ criterionId: "a", result: "caution" }),
    criterion({ criterionId: "b", result: "fail" }),
    criterion({ criterionId: "c", result: "unknown" }),
  ])
  assert.deepEqual(
    comparison.rows.map((row) => row.state),
    ["partial", "mismatch", "unknown"],
  )
})

test("deriveAlternativeComparison: summary score is the fraction of matching rows", () => {
  const comparison = deriveAlternativeComparison([
    criterion({ criterionId: "a", result: "pass" }),
    criterion({ criterionId: "b", result: "pass" }),
    criterion({ criterionId: "c", result: "fail" }),
    criterion({ criterionId: "d", result: "unknown" }),
  ])
  assert.equal(comparison.summaryScore, 0.5)
})

test("deriveAlternativeComparison: preserves criteria order and copies id/label verbatim", () => {
  const comparison = deriveAlternativeComparison([
    criterion({ criterionId: "shampoo.scalp_route", label: "Kopfhaut-Fokus" }),
    criterion({ criterionId: "shampoo.cleansing_intensity", label: "Reinigungsstärke" }),
  ])
  assert.deepEqual(
    comparison.rows.map((row) => [row.rowId, row.label]),
    [
      ["shampoo.scalp_route", "Kopfhaut-Fokus"],
      ["shampoo.cleansing_intensity", "Reinigungsstärke"],
    ],
  )
})

test("deriveAlternativeComparison: a row never carries anything beyond rowId/label/state", () => {
  const comparison = deriveAlternativeComparison([criterion()])
  const row = comparison.rows[0] as ScanComparisonRow
  assert.deepEqual(Object.keys(row).sort(), ["label", "rowId", "state"])
})

test("deriveAlternativeComparison: is a pure function — same input, same output, no mutation", () => {
  const input = [criterion({ criterionId: "x" })]
  const frozen = Object.freeze([...input])
  const first = deriveAlternativeComparison(frozen)
  const second = deriveAlternativeComparison(frozen)
  assert.deepEqual(first, second)
})

test("Scan analytics is PostHog-only", () => {
  for (const eventName of scanEventNames) {
    assert.deepEqual(eventRoutes[eventName], { customerio: false, meta: false, posthog: true })
  }
})

test("noOpScanAnalytics never forwards events", () => {
  const calls: unknown[] = []
  const originalCapture = posthog.capture
  posthog.capture = ((...args: unknown[]) => {
    calls.push(args)
    return true
  }) as typeof posthog.capture

  try {
    noOpScanAnalytics.track("scan_started", {})
    noOpScanAnalytics.track("scan_buy_clicked", { verdict: "ideal" })
  } finally {
    posthog.capture = originalCapture
  }

  assert.equal(calls.length, 0)
})

test("Scan analytics factory only fires with analytics consent", () => {
  const calls: Array<{ eventName: string; payload: object }> = []
  const recordingTrackAppEvent = ((eventName: string, payload: object) =>
    calls.push({ eventName, payload })) as ScanAnalyticsPort["track"]

  const declined = createConsentAwareScanAnalytics({
    loadConsent: () => ({ essential: true, analytics: false, marketing: false, ts: 0 }),
    trackAppEvent: recordingTrackAppEvent,
  })
  declined.track("scan_started", {})
  declined.track("scan_buy_clicked", { verdict: "ideal" })
  declined.track("scan_not_found", unknownJourney)
  declined.track("scan_submission_created", { category: "conditioner", ...submittedJourney })
  assert.equal(calls.length, 0)

  const unset = createConsentAwareScanAnalytics({
    loadConsent: () => null,
    trackAppEvent: recordingTrackAppEvent,
  })
  unset.track("scan_started", {})
  assert.equal(calls.length, 0)

  const consented = createConsentAwareScanAnalytics({
    loadConsent: () => ({ essential: true, analytics: true, marketing: false, ts: 0 }),
    trackAppEvent: recordingTrackAppEvent,
  })
  consented.track("scan_started", {})
  consented.track("scan_decoded", { msToDecode: 812, format: "ean_13" })
  consented.track("scan_result_shown", {
    verdict: "ideal",
    category: "shampoo",
    inCatalog: true,
    snapshotSource: "refined",
  })
  consented.track("scan_not_found", unknownJourney)
  consented.track("scan_retailer_search", {
    catalogCount: 1,
    retailerCount: 2,
    outcome: "ok",
    durationMs: 340,
    trigger: "auto",
  })
  consented.track("scan_retailer_result_opened", { categoryLabel: "Conditioner" })
  consented.track("scan_submission_created", { category: "conditioner", ...submittedJourney })
  consented.track("scan_fallback_search_used", { trigger: "timeout" })
  consented.track("scan_saved", { kind: "routine", verdict: "ideal" })
  consented.track("scan_buy_clicked", { verdict: "mismatch" })

  assert.deepEqual(calls, [
    { eventName: "scan_started", payload: {} },
    { eventName: "scan_decoded", payload: { msToDecode: 812, format: "ean_13" } },
    {
      eventName: "scan_result_shown",
      payload: {
        verdict: "ideal",
        category: "shampoo",
        inCatalog: true,
        snapshotSource: "refined",
      },
    },
    { eventName: "scan_not_found", payload: unknownJourney },
    {
      eventName: "scan_retailer_search",
      payload: {
        catalogCount: 1,
        retailerCount: 2,
        outcome: "ok",
        durationMs: 340,
        trigger: "auto",
      },
    },
    {
      eventName: "scan_retailer_result_opened",
      payload: { categoryLabel: "Conditioner" },
    },
    {
      eventName: "scan_submission_created",
      payload: { category: "conditioner", ...submittedJourney },
    },
    { eventName: "scan_fallback_search_used", payload: { trigger: "timeout" } },
    { eventName: "scan_saved", payload: { kind: "routine", verdict: "ideal" } },
    { eventName: "scan_buy_clicked", payload: { verdict: "mismatch" } },
  ])
})

