test("Scan events map to PostHog with the documented snake_case properties", () => {
  const originalCapture = posthog.capture
  const calls: unknown[][] = []
  posthog.capture = ((...args: unknown[]) => {
    calls.push(args)
    return true
  }) as typeof posthog.capture

  try {
    postHogDestination.track("scan_started", {})
    postHogDestination.track("scan_decoded", { msToDecode: 900, format: "ean_8" })
    postHogDestination.track("scan_result_shown", {
      verdict: "not_needed",
      category: "oil",
      inCatalog: false,
      snapshotSource: "initial",
    })
    postHogDestination.track("scan_not_found", unknownJourney)
    postHogDestination.track("scan_retailer_search", {
      catalogCount: 3,
      retailerCount: 5,
      outcome: "unavailable",
      durationMs: 902,
      trigger: "submit",
    })
    postHogDestination.track("scan_retailer_result_opened", { categoryLabel: null })
    postHogDestination.track("scan_submission_created", { category: "mask", ...submittedJourney })
    postHogDestination.track("scan_fallback_search_used", { trigger: "manual" })
    postHogDestination.track("scan_saved", { kind: "merkliste", verdict: "supportive" })
    postHogDestination.track("scan_buy_clicked", { verdict: "merkliste" })
  } finally {
    posthog.capture = originalCapture
  }

  assert.deepEqual(calls, [
    ["scan_started", {}],
    ["scan_decoded", { ms_to_decode: 900, format: "ean_8" }],
    [
      "scan_result_shown",
      { verdict: "not_needed", category: "oil", in_catalog: false, snapshot_source: "initial" },
    ],
    [
      "scan_not_found",
      {
        identified: true,
        suggested_category: "shampoo",
        scan_interaction_id: "test-sheet-1",
        ms_to_unknown_sheet_ready: 430,
      },
    ],
    [
      "scan_retailer_search",
      {
        catalog_count: 3,
        retailer_count: 5,
        outcome: "unavailable",
        duration_ms: 902,
        trigger: "submit",
      },
    ],
    ["scan_retailer_result_opened", { category_label: null }],
    [
      "scan_submission_created",
      {
        category: "mask",
        suggested_category: "shampoo",
        selection_path: "grid",
        scan_interaction_id: "test-sheet-1",
        ms_confirmation_to_pending: 180,
        intake_path: "scan",
      },
    ],
    ["scan_fallback_search_used", { trigger: "manual" }],
    ["scan_saved", { kind: "merkliste", verdict: "supportive" }],
    ["scan_buy_clicked", { verdict: "merkliste" }],
  ])
})

