test("scan_result_shown reports a not_needed verdict as a catalog hit, not a miss", () => {
  const product = { productId: "prod-1", name: "Shampoo X" }
  // Both verdict branches only exist once the barcode resolved to a catalog product.
  assert.equal(scanResultShownInCatalog({ kind: "in_catalog", product }), true)
  assert.equal(scanResultShownInCatalog({ kind: "not_needed", product }), true)
  // Defensive: no product header means no catalog resolution happened.
  assert.equal(scanResultShownInCatalog({ kind: "not_needed", product: null }), false)
})

test(`matchCatalogProducts typo table: ${label} ("${query}")`, () => {
    assert.deepEqual(ids(query), expected)
  })

test("matchCatalogProducts: tokens under 5 chars compare whole words, not word prefixes", () => {
  // Prefix matching would let "oil" (1 edit) hit "Olaplex" via "ol".
  assert.deepEqual(ids("oil"), [])
  // A whole-word typo still matches: "olaplx" is 6 chars, "glss" a whole-word deletion.
  assert.deepEqual(ids("olaplx"), ["olaplex"])
  assert.deepEqual(ids("glss"), ["gliss"])
})

test("matchCatalogProducts: very short tokens (< 3 chars) get no typo tolerance", () => {
  // With 1 edit, "xy" would match any title token that merely starts with "x" or "y".
  assert.deepEqual(ids("xy"), [])
})

test("matchCatalogProducts: exact title → substring → token → typo-only tiers, sort_order only breaks ties within a tier", () => {
  const rows = [
    row("typo-only", "Shampo Deluxe", "Marke", { sort_order: 0 }),
    row("token-reordered", "Deluxe Shampoo", "Marke", { sort_order: 0 }),
    row("substring", "Shampoo Deluxe Plus", "Marke", { sort_order: 5 }),
    row("exact", "Shampoo Deluxe", "Marke", { sort_order: 9 }),
  ]
  const ranked = matchCatalogProducts(rows, "marke shampoo deluxe").map((candidate) => candidate.id)
  assert.deepEqual(ranked, ["exact", "substring", "token-reordered", "typo-only"])
})

test("matchCatalogProducts: within the typo tier the existing sort_order → name → id tiebreak holds", () => {
  const rows = [
    row("b", "Shampo B", "Marke", { sort_order: 2 }),
    row("a", "Shampo A", "Marke", { sort_order: 2 }),
    row("c", "Shampo C", "Marke", { sort_order: 1 }),
  ]
  assert.deepEqual(
    matchCatalogProducts(rows, "shampoo").map((candidate) => candidate.id),
    ["c", "a", "b"],
  )
})

test("matchCatalogProducts: plain substring matching is unchanged (case-insensitive, over the identity title)", () => {
  assert.deepEqual(ids("PURE SHAMP"), ["elvital"])
  assert.deepEqual(ids("aqua revive"), ["gliss"])
})

test("maskAlternative: withholds identity, productId, image, price and net content", () => {
  const masked = maskAlternative(alternative())
  assert.deepEqual(Object.keys(masked).sort(), ["comparison", "verdict", "verdictLabel"])
})

test("maskAlternative: keeps the alternative's own verdict and verdict label", () => {
  const masked = maskAlternative(
    alternative({ verdict: "supportive", verdictLabel: "Passt eingeschränkt" }),
  )
  assert.equal(masked.verdict, "supportive")
  assert.equal(masked.verdictLabel, "Passt eingeschränkt")
})

test("maskAlternative: derives comparison rows from the alternative's own criteria", () => {
  const masked = maskAlternative(alternative())
  assert.deepEqual(masked.comparison.rows, [
    { rowId: "shampoo.scalp_route", label: "Kopfhaut-Fokus", state: "match" },
  ])
  assert.equal(masked.comparison.summaryScore, 1)
})

test("maskAlternative: an alternative with no carried criteria yields an empty comparison", () => {
  const masked = maskAlternative(alternative({ criteria: undefined }))
  assert.deepEqual(masked.comparison, { rows: [], summaryScore: 0 })
})

test("maskAlternative: does not mutate the input", () => {
  const source = alternative()
  const snapshot = JSON.parse(JSON.stringify(source))
  maskAlternative(source)
  assert.deepEqual(source, snapshot)
})

test("maskScanVerdictPayload: masks every alternative, leaves every other field untouched", () => {
  const masked = maskScanVerdictPayload(inCatalogVerdict)
  assert.equal(masked.alternatives.length, 2)
  assert.equal(masked.verdictTitle, inCatalogVerdict.verdictTitle)
  assert.equal(masked.coverage, inCatalogVerdict.coverage)
  assert.equal(masked.dimensions, inCatalogVerdict.dimensions)
  for (const entry of masked.alternatives as ScanMaskedAlternative[]) {
    assert.deepEqual(Object.keys(entry).sort(), ["comparison", "verdict", "verdictLabel"])
  }
})

test("maskScanVerdictPayload: an empty alternatives list stays empty", () => {
  const masked = maskScanVerdictPayload({ ...inCatalogVerdict, alternatives: [] })
  assert.deepEqual(masked.alternatives, [])
})

test("scan name-only submission migration: identifier-based scan rows are unaffected (byte-identical EAN lane)", async (t) => {
  const pg = await database()
  t.after(async () => pg.close())

  await pg.query(
    `INSERT INTO public.product_submissions
       (user_id, category, source, status, scanned_identifier_type, scanned_identifier_value)
     VALUES ($1, 'shampoo', 'scan', 'pending_review', 'ean', '4006381333931')`,
    [userA],
  )
  const rows = await pg.query("SELECT count(*)::int AS count FROM public.product_submissions")
  assert.equal((rows.rows[0] as { count: number }).count, 1)
})

