  const second = entry("pre_heat_application", known("supportive", { cautions: 1 }), {
    matches: 2,
    total: 3,
  })
  assert.equal(selectBestRoleEvaluation([first, second]), first)
  assert.equal(selectBestRoleEvaluation([second, first]), second)
})

